import java.util.concurrent.locks.ReentrantLock;

public class SectionCritique {
    private final ReentrantLock lock = new ReentrantLock();

    void attendreSousVerrou() throws InterruptedException {
        lock.lock();
        try {
            Thread.sleep(1000); // le thread virtuel peut se demonter : pas de pinning
        } finally {
            lock.unlock();
        }
    }
}
